+static void counting_sort_pass(uint32_t* src, uint32_t* dst, size_t n, int shift) {
+    // Base 2^11 = 2048
+    constexpr int RADIX = 2048;
+    int count[RADIX] = {0};
+    constexpr int MASK = 0x7FF; 
+    // Count frequencies
+    for (size_t i = 0; i < n; ++i) {
+        count[(src[i] >> shift) & MASK]++;
+    }
+
+    // Calculate prefix sums
+    int total = 0;
+    for (int i = 0; i < RADIX; ++i) {
+        int current_count = count[i];
+        count[i] = total;
+        total += current_count;
+    }
+
+    // Place elements into destination array
+    for (size_t i = 0; i < n; ++i) {
+        int bucket = (src[i] >> shift) & MASK;
+        dst[count[bucket]++] = src[i];
+    }
+}
+
+static bool is_sorted_asc(uint32_t* a, size_t n) {
+    if (n < 2) return true;
+    for (size_t i = 0; i < n - 1; ++i) {
+        if (a[i] > a[i+1]) return false;
+    }
+    return true;
 }

